  ["Pineapple stubble", "{rastrojo_pina_avail}", "{rastrojo_pina_fresh}", "{rastrojo_pina_removed}", "{rastrojo_pina_dried}", "{rastrojo_pina_water}", "{rastrojo_pina_heat}", "{rastrojo_pina_margin}", "{rastrojo_pina_be}"],
  ["Coffee pulp", "{pulpa_cafe_avail}", "{pulpa_cafe_fresh}", "{pulpa_cafe_removed}", "{pulpa_cafe_dried}", "{pulpa_cafe_water}", "{pulpa_cafe_heat}", "{pulpa_cafe_margin}", "{pulpa_cafe_be}"],
